import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))


def run():
    try:
        from checkout import checkout
    except Exception as exc:
        return "error", 2, f"Import failed: {type(exc).__name__}: {exc}"

    try:
        result = checkout(1250)
    except TypeError as exc:
        if "'int' object is not subscriptable" in str(exc):
            return "reproduced", 1, "checkout(1250) raises TypeError instead of returning 1250"
        return "error", 2, f"Unexpected TypeError: {exc}"
    except Exception as exc:
        return "error", 2, f"Unexpected execution failure: {type(exc).__name__}: {exc}"

    if result != 1250:
        return "reproduced", 1, f"checkout(1250) returned {result!r} instead of 1250"
    return "passed", 0, "checkout(1250) returns 1250"


outcome, code, reason = run()
print("NEIN_PROBE_RESULT " + json.dumps({"check": "checkout-total-contract", "outcome": outcome, "reason": reason}))
sys.exit(code)

import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
CHECK = "checkout-total-contract"


def emit(outcome, reason, code):
    print("NEIN_PROBE_RESULT " + json.dumps({"check": CHECK, "outcome": outcome, "reason": reason}))
    raise SystemExit(code)


try:
    from checkout import checkout
    if not callable(checkout):
        raise RuntimeError("checkout is not callable")
except Exception as exc:
    emit("error", f"Setup failed: {type(exc).__name__}: {exc}", 2)

failures = []
for cents in (1250, 0):
    try:
        actual = checkout(cents)
    except TypeError as exc:
        if str(exc) != "'int' object is not subscriptable":
            emit("error", f"Unexpected TypeError: {exc}", 2)
        failures.append(f"checkout({cents}) raises TypeError: {exc}")
    except Exception as exc:
        emit("error", f"Unexpected execution failure: {type(exc).__name__}: {exc}", 2)
    else:
        if actual != cents:
            failures.append(f"checkout({cents}) returned {actual!r}, expected {cents}")

if failures:
    emit("reproduced", "; ".join(failures), 1)
emit("passed", "checkout(1250) returns 1250 and checkout(0) returns 0", 0)

import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { resolve, join } from "node:path";
import { pathToFileURL } from "node:url";
import { mock } from "bun:test";

const check = process.argv[2];
function result(outcome: string, reason: string, code: number): never {
  process.stdout.write(`NEIN_PROBE_RESULT ${JSON.stringify({ check, outcome, reason })}\n`);
  process.exit(code);
}
try {
  if (!["receipt-terminal-width", "expanded-output-controls"].includes(check)) throw new Error("Unknown check");
  const version = JSON.parse(readFileSync("runtime.json", "utf8")).pi.version;
  const roots = [process.env.N_EIN_HOME, join(homedir(), ".n_ein")].filter(Boolean) as string[];
  const modules = roots.map(root => join(root, "runtimes/pi", version, "global/node_modules"))
    .find(path => existsSync(join(path, "@earendil-works/pi-coding-agent/package.json")));
  if (!modules) throw new Error(`Pi ${version} runtime is required`);
  const load = (path: string) => import(pathToFileURL(join(modules, path)).href);
  const tui = await load("@earendil-works/pi-tui/dist/index.js");
  mock.module("@earendil-works/pi-tui", () => tui);
  const { initTheme } = await load("@earendil-works/pi-coding-agent/dist/modes/interactive/theme/theme.js");
  initTheme("dark", false);
  const { ToolExecutionComponent } = await load("@earendil-works/pi-coding-agent/dist/modes/interactive/components/tool-execution.js");
  const { readRenderers } = await load("@earendil-works/pi-coding-agent/dist/core/tools/renderers/read.js");
  let resolver: any;
  if (existsSync("pi-package/extensions/tools-view.ts")) {
    const { default: register } = await import(pathToFileURL(resolve("pi-package/extensions/tools-view.ts")).href);
    register({ registerToolRenderer(fn: any) { resolver = fn; } });
    if (typeof resolver !== "function") throw new Error("Extension did not register its resolver");
  }
  const tool = check === "receipt-terminal-width" ? "read" : "external_search";
  const native = tool === "read" ? readRenderers : {};
  const definition = resolver ? resolver(tool, () => native) : native;
  const args = tool === "read" ? { path: `docs/${"界".repeat(80)}.txt` } : { query: "example" };
  const row = new ToolExecutionComponent(tool, "probe-call", args, { showImages: false }, definition, { requestRender() {} }, process.cwd());
  row.setArgsComplete();
  row.markExecutionStarted();
  const output = check === "expanded-output-controls" ? "hello\u001b[2Jthere" : "example\n";
  row.updateResult({ content: [{ type: "text", text: output }], details: undefined, isError: false });
  row.setExpanded(check === "expanded-output-controls");
  const width = 60;
  const lines: string[] = row.render(width);
  if (!lines.length || !lines.some(line => line.includes(tool === "read" ? "docs/" : "hello"))) throw new Error("Tool row did not render its expected content");
  if (check === "receipt-terminal-width") {
    const measured = Math.max(...lines.map(line => tui.visibleWidth(line)));
    if (measured > width) result("reproduced", `Collapsed read row occupies ${measured} terminal columns at width ${width}`, 1);
    result("passed", `Read row was rendered and every line fits within ${width} terminal columns`, 0);
  }
  const injected = lines.some(line => line.includes("\u001b[2J"));
  if (injected) result("reproduced", "Expanded generic tool output retains the clear-screen terminal command ESC[2J", 1);
  if (!lines.join("").includes("there")) throw new Error("Output suffix was not rendered");
  result("passed", "Expanded generic tool output renders both words but removes the clear-screen terminal command", 0);
} catch (error) {
  result("error", error instanceof Error ? error.message : String(error), 2);
}

