import ts from 'typescript'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

const check = 'generate-planning-input-types'
function finish(outcome: 'reproduced' | 'passed' | 'error', reason: string): never {
  console.log(`NEIN_PROBE_RESULT ${JSON.stringify({ check, outcome, reason })}`)
  process.exit(outcome === 'reproduced' ? 1 : outcome === 'error' ? 2 : 0)
}

try {
  const configPath = resolve('.nuxt/tsconfig.server.json')
  const config = ts.readConfigFile(configPath, ts.sys.readFile)
  if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, '\n'))
  const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, resolve('.nuxt'))
  if (parsed.errors.length) throw new Error(ts.formatDiagnosticsWithColorAndContext(parsed.errors, {
    getCanonicalFileName: x => x, getCurrentDirectory: ts.sys.getCurrentDirectory, getNewLine: () => '\n',
  }))
  const endpoint = resolve('server/api/generate.post.ts')
  const sourceText = readFileSync(endpoint, 'utf8')
  const assignments = ['center: centro', 'complementaryModules: complementarios']
  for (const assignment of assignments) {
    if (!sourceText.includes(assignment)) throw new Error(`No se encuentra la asignacion ${assignment}`)
  }
  const program = ts.createProgram(parsed.fileNames, { ...parsed.options, noEmit: true })
  const source = program.getSourceFile(endpoint)
  if (!source) throw new Error('El proyecto no incluye el endpoint generate')
  const diagnostics = program.getSemanticDiagnostics(source)
  const failures = diagnostics.filter(d => d.code === 2322 && d.start !== undefined && assignments.some(a => {
    const start = sourceText.indexOf(a)
    return d.start! >= start && d.start! < start + a.length
  }))
  const dependencyFailure = diagnostics.find(d => [2307, 2688, 6053].includes(d.code))
  if (dependencyFailure) throw new Error(ts.flattenDiagnosticMessageText(dependencyFailure.messageText, '\n'))
  if (failures.length) finish('reproduced', failures.map(d => ts.flattenDiagnosticMessageText(d.messageText, ' ')).join(' | '))
  finish('passed', 'Las asignaciones center y complementaryModules cumplen PlanningInput sin errores TS2322')
} catch (error) {
  finish('error', error instanceof Error ? error.message : String(error))
}

import ts from 'typescript'
import path from 'node:path'
import { existsSync } from 'node:fs'

const check = 'generate-planning-types'
function finish(outcome: string, reason: string, code: number): never {
  process.stdout.write(`NEIN_PROBE_RESULT ${JSON.stringify({ check, outcome, reason })}\n`)
  process.exit(code)
}

try {
  const root = process.cwd()
  const handler = path.join(root, 'server/api/generate.post.ts')
  const globals = path.join(root, '.previewer-probes/virtual-nitro-globals.d.ts')
  if (!existsSync(handler)) throw new Error('Missing tracked generate handler')
  const declarations = `
    declare function defineEventHandler<T>(handler: (event: any) => T): any;
    declare function readBody(event: any): Promise<any>;
    declare function createError(input: any): Error;
    declare function setResponseStatus(event: any, status: number): void;
    declare function $fetch<T>(url: string): Promise<T>;
  `
  const options: ts.CompilerOptions = {
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    strict: true,
    skipLibCheck: true,
    noEmit: true,
    types: [],
  }
  const host = ts.createCompilerHost(options)
  const originalGet = host.getSourceFile.bind(host)
  host.getSourceFile = (file, languageVersion, onError, shouldCreateNewSourceFile) => file === globals
    ? ts.createSourceFile(file, declarations, languageVersion, true)
    : originalGet(file, languageVersion, onError, shouldCreateNewSourceFile)
  const program = ts.createProgram([handler, globals], options, host)
  if (!program.getSourceFile(handler) || !program.getSourceFile(path.join(root, 'server/utils/calculatePlanning.ts'))) {
    throw new Error('Handler or real PlanningInput was not loaded by TypeScript')
  }
  const diagnostics = ts.getPreEmitDiagnostics(program)
  const setupErrors = diagnostics.filter(d => [2307, 2688, 6053].includes(d.code) || (d.file?.fileName === handler && d.code === 2304))
  if (setupErrors.length) throw new Error(ts.formatDiagnosticsWithColorAndContext(setupErrors, { getCanonicalFileName: f => f, getCurrentDirectory: () => root, getNewLine: () => '\n' }))
  const failures = diagnostics.filter(d => d.file?.fileName === handler && d.code === 2322 && /Center|ComplementaryModule/.test(ts.flattenDiagnosticMessageText(d.messageText, ' ')))
  if (failures.length) {
    finish('reproduced', failures.map(d => {
      const position = d.file!.getLineAndCharacterOfPosition(d.start!)
      return `generate.post.ts:${position.line + 1} TS${d.code} ${ts.flattenDiagnosticMessageText(d.messageText, ' ')}`
    }).join('; '), 1)
  }
  finish('passed', 'The tracked generate handler assigns center and complementaryModules to the real PlanningInput without type errors', 0)
} catch (error) {
  finish('error', error instanceof Error ? error.stack || error.message : String(error), 2)
}

