let result;
try {
  const { Registry } = await import('../registry.ts');
  const registry = new Registry();
  let finishOld;
  let finishNew;
  const oldGate = new Promise(resolve => { finishOld = resolve; });
  const newGate = new Promise(resolve => { finishNew = resolve; });
  let oldStarted = false;
  let newStarted = false;
  const oldRun = registry.run('same-key', () => { oldStarted = true; return oldGate; });
  const oldEntry = registry.active.get('same-key');
  const newRun = registry.run('same-key', () => { newStarted = true; return newGate; });
  const newEntry = registry.active.get('same-key');
  await Promise.resolve();
  if (!oldStarted || !newStarted || !(newEntry instanceof Promise) || newEntry === oldEntry) {
    throw new Error('Setup did not create two overlapping jobs with the newest entry exposed');
  }
  finishOld('old-result');
  if (await oldRun !== 'old-result') throw new Error('Old job did not return its own result');
  const preservedNewest = registry.active.get('same-key') === newEntry;
  finishNew('new-result');
  if (await newRun !== 'new-result') throw new Error('New job did not return its own result');
  if (registry.active.has('same-key')) throw new Error('Completed newest job was not cleaned up');
  result = {
    check: 'replacement-survives-old-completion',
    outcome: preservedNewest ? 'passed' : 'reproduced',
    reason: preservedNewest
      ? 'Completing old work preserved the newer pending entry until the newer work finished'
      : 'Completing old work removed the newer entry while the newer work was still pending'
  };
} catch (error) {
  result = { check: 'replacement-survives-old-completion', outcome: 'error', reason: String(error) };
}
process.stdout.write(`NEIN_PROBE_RESULT ${JSON.stringify(result)}\n`);
process.exitCode = result.outcome === 'error' ? 2 : result.outcome === 'reproduced' ? 1 : 0;

import { Registry } from '../registry.ts';

const check = 'registry-replacement-cleanup';
function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
function requireSetup(value, message) {
  if (!value) throw new Error(message);
}

async function exercise() {
  const failures = [];
  for (const rejects of [false, true]) {
    const registry = new Registry();
    const older = deferred();
    const newer = deferred();
    const failure = new Error('expected work failure');
    const oldResult = registry.run('key', () => older.promise).then(
      value => ({ value }), error => ({ error })
    );
    const oldEntry = registry.active.get('key');
    const newResult = registry.run('key', () => newer.promise);
    const newEntry = registry.active.get('key');
    requireSetup(oldEntry && newEntry && oldEntry !== newEntry, 'replacement was not registered');
    await Promise.resolve();
    if (rejects) older.reject(failure);
    else older.resolve('older');
    const outcome = await oldResult;
    requireSetup(rejects ? outcome.error === failure : outcome.value === 'older', 'old result changed unexpectedly');
    if (registry.active.get('key') !== newEntry) {
      failures.push(`older ${rejects ? 'rejection' : 'completion'} removed the still-pending replacement`);
    }
    newer.resolve('newer');
    requireSetup(await newResult === 'newer', 'new result changed unexpectedly');
    if (registry.active.has('key')) failures.push('finished replacement was not cleaned up');
  }
  for (const rejects of [false, true]) {
    const registry = new Registry();
    const work = deferred();
    const failure = new Error('expected single failure');
    const result = registry.run('single', () => work.promise).then(
      value => ({ value }), error => ({ error })
    );
    requireSetup(registry.active.has('single'), 'single work was not registered');
    await Promise.resolve();
    if (rejects) work.reject(failure);
    else work.resolve('single');
    const outcome = await result;
    requireSetup(rejects ? outcome.error === failure : outcome.value === 'single', 'single result changed unexpectedly');
    if (registry.active.has('single')) failures.push('single finished work was not cleaned up');
  }
  return failures;
}

try {
  const failures = await exercise();
  const outcome = failures.length ? 'reproduced' : 'passed';
  console.log('NEIN_PROBE_RESULT ' + JSON.stringify({ check, outcome, reason: failures.length ? failures.join('; ') : 'Pending replacements survive older completion and rejection; results and final cleanup are preserved.' }));
  process.exitCode = failures.length ? 1 : 0;
} catch (error) {
  console.log('NEIN_PROBE_RESULT ' + JSON.stringify({ check, outcome: 'error', reason: String(error.stack || error) }));
  process.exitCode = 2;
}
